Thanks Daniel, this is the full program. I tweaked some things and it seems to be working but if there's any glaring errors that I'm missing by staring at this constantly, I would love to hear them.

data{
int<lower=0> N;

vector[N] Y_treatment;

vector[N] y_ss;
vector[N] x_ss;

vector[N] xselect;
real constant; //this is the N/2 * log(2pi) constant in the likelihood function
}

parameters{
  real<lower=0> sigma1;
  real<lower=0> sigma2;
  corr_matrix[3] Lambda;
  real beta_treat;
  real betaselect;
  real beta_untreat;
}
transformed parameters {

real ratio_treat;
real ratio_untreat;

  matrix[3,3] covmat;

  {
    vector[3] sdvector;
    sdvector[1] <- 1;
    sdvector[2] <- sigma1;
    sdvector[3] <- sigma2;

    covmat <- diag_pre_multiply(sdvector, diag_post_multiply(Lambda, sdvector));
  }

ratio_treat<-Lambda[1,3] /sigma2;
ratio_untreat<-Lambda[1,2] /sigma1;

}
model{

vector[N] lp;
    for(i in 1:N){
        if(Y_treatment[i]==1){

lp[i]<-constant+(-log(sigma2)-0.5*((y_ss[i]-beta_treat*x_ss[i])/sigma2)^2+log(Phi((betaselect*xselect[i]+(ratio_treat)*(y_ss[i]-beta_treat*x_ss[i]))/((1-Lambda[1,3]^2)^.5))));
}
else{

lp[i]<-constant+(-log(sigma1)-0.5*((y_ss[i]-beta_untreat*x_ss[i])/sigma1)^2+log(Phi(-1*((betaselect*xselect[i]+(ratio_untreat)*(y_ss[i]-beta_untreat*x_ss[i]))/((1-Lambda[1,2]^2)^.5)))));

}
}
sigma1 ~ cauchy(0,1);
sigma2 ~ cauchy(0,1);
beta_treat ~ normal(0,1);
beta_untreat ~ normal(0,1);
betaselect ~ normal(0,1);

increment_log_prob((lp));
}

